    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    # Adjust thrust direction based on gate proximity
    if G1_X - 1.0 <= x <= G1_X + 1.0:
        # In Gate 1 area: prioritize horizontal movement
        thrust_mag = max(20.0, thrust_mag)
        wx = G1_X
        wy = 1.9
    if G2_X - 1.0 <= x <= G2_X + 1.0:
        # In Gate 2 area: prioritize horizontal movement
        thrust_mag = max(20.0, thrust_mag)
        wx = G2_X
        wy = 2.4

    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)

    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 10.0)
        return

    ux = dx / dist
    uy = dy / dist

    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Add vertical thrust to maintain y-position in gates
    if y < 1.4:
        fy += 15.0  # Increased from 10.0 to minimize heat
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(5.0, (1.2 - y) * 3.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 10.0  # Reduced from 60.0

    if x > 25.0 and y < 3.0:
        fy += 10.0  # Reduced from 90.0

    # Adjust for wind force
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy -= wind_fy

    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 1.2  # Reduced from 2.0 to limit total thrust

    if y < 1.4:
        cap = max(cap, 30.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        cap = max(cap, 40.0)

    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    sandbox.apply_thrust(fx, fy)
